// Generated by packages/kit/context/build.mjs from reference.md and recipes/: do not edit.
/** The kit's reference, for Iso building an artifact. */
export const REFERENCE: string = "# The kit (isorite kit 1)\n\nAn artifact is one HTML file: markup, perhaps a script, and a manifest in its `<head>`. isorite gives it the kit:\nthe look (every colour, font and corner), the elements below, and `window.iso`. Write what it shows and does, never\nhow it looks: no colour, font family or border-radius of your own.\n\n## The file\n\n```html\n<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>Title</title>\n<meta name=\"description\" content=\"One sentence: what it shows, and what can be done with it.\">\n<meta name=\"isorite:kit\" content=\"1\">\n<meta name=\"isorite:uses\" content=\"runs.csv other.csv\">\n<style>/* layout only, if needed */</style>\n</head>\n<body>\n<iso-page>\n  <header><h1>Title</h1><p>The question it answers, in a sentence or two.</p></header>\n  <iso-grid>\n    <iso-panel class=\"wide\"><h2>Name <span>a short reading</span></h2> … </iso-panel>\n    <iso-panel><h2>…</h2> … </iso-panel>\n  </iso-grid>\n</iso-page>\n</body>\n</html>\n```\n\n`write_artifact` fills in the title, description and manifest from its arguments, so they are always right.\n\n## Layout\n\n- `<iso-grid>`: panels in two columns (`style=\"--cols: 3\"` for three); `<iso-panel class=\"wide\">` spans the row.\n- `<iso-panel>`: its first child is `<h2>`; a `<span>` in the `h2` is a soft aside. A `<p>` in a panel is a\n  caption: what the panel shows, in a sentence.\n- `<iso-row>`: controls side by side. `<iso-stats>`: big numbers side by side.\n\n## Data, with no script\n\nEvery element with `data=\"file.csv\"` reads it itself. Several files are one table:\n`data=\"euler.csv leapfrog.csv\"` adds a column `file` (`euler`, `leapfrog`) to compare them with `by=\"file\"`.\n`where=\"integrator=leapfrog\"` keeps some rows; `where=\"t<=$t\"` compares with a control's value. `abs(col)` is a\ncolumn's size.\n\n- `<iso-chart data=\"f.csv\" x=\"t\" y=\"energy\" by=\"body\">`: a chart.\n  - `type`: `line` (default), `dot`, `bar`, `area`, `step`.\n  - `y` may name several columns: `y=\"kinetic potential total\"`, each its own line.\n  - `by`: a column whose values are the series.\n  - `x-scale`, `y-scale`: `linear` or `log`, or `$name` to follow a control (`y-scale=\"$scale\"`).\n  - `x-label`, `y-label`: the axis with its unit (`\"time (s)\"`). `height` in pixels (260).\n  - `at=\"t\"`: follows the control `t`. A rule where x is its value; or, when the data has a column `t` and x is\n    another column (a path in x and y over time), a dot on each series at the row whose `t` is nearest it.\n- `<iso-table data=\"f.csv\" columns=\"a b c\" limit=\"50\">`: the rows.\n- `<iso-stat data=\"f.csv\" column=\"err\" of=\"max\" label=\"worst error\" tone=\"gold\">`: one number. `of`: `min`, `max`,\n  `mean`, `sum`, `count`, `first`, `last`. Tones: `gold`, `blue`, `green`, `rose`. Without `data`, set it from a\n  script: `el.value = 0.0023`.\n- `<iso-chart3d data=\"f.csv\" x=\"x\" y=\"y\" z=\"z\" by=\"body\" at=\"t\">`: points or paths in 3D, turned by dragging.\n- `<iso-model src=\"part.glb\">`: a 3D model (glTF, GLB, STL, OBJ), turned by dragging. List it in isorite:uses.\n\n## Text and maths\n\n- A `<p>` in a panel is its caption. Maths is written as in a note: `$E = \\tfrac12 m v^2$` inline, `$$…$$` on a\n  line of its own; the kit sets it. `<iso-math>\\frac{a}{b}</iso-math>` is a formula alone.\n- Never name the theme's colours in text (\"the lattice line\"): a chart's legend says which series is which.\n\n## Controls\n\nEach writes its value to `iso.state[name]`; elements that name it (`at=\"t\"`, `$t`) follow it.\n\n- `<iso-slider name=\"dt\" label=\"time step\" min=\"0.001\" max=\"0.05\" step=\"0.001\" value=\"0.01\" digits=\"3\">`\n- `<iso-select name=\"scale\" label=\"scale\" options=\"linear log\">`: one of several.\n- `<iso-toggle name=\"softened\" label=\"softened\" value=\"true\">`: on or off.\n- `<iso-play name=\"t\" min=\"0\" max=\"12\" speed=\"1.5\">`: plays `iso.state.t` from min to max, and pauses.\n- `<iso-note href=\"physics/softening\">softening</iso-note>`: opens a note in isorite.\n\n## Script, when markup isn't enough\n\nFor a simulation or anything computed. Put it at the end of the body.\n\n- `const rows = await iso.data(\"f.csv\")`: the rows as objects, numbers as numbers.\n- `iso.state.name`, `iso.watch((name) => …)`: the shared state; `watch` runs after any change.\n- `iso.loop((dt, t) => …)`: runs every frame (dt in seconds), paused when hidden. Returns a stop function.\n- `<iso-canvas height=\"320\" id=\"sim\">` and `document.getElementById(\"sim\").draw = (ctx, w, h, t) => { … }`: draw on\n  a canvas sized to its panel; call `.redraw()` after a change. `t` is the theme: `t.text`, `t.soft`, `t.faint`,\n  `t.line`, `t.lattice` (blue), `t.growth` (gold), `t.malachite` (green), `t.rose`, `t.series[i]`, `t.ui` (the font).\n- A chart of what the script computes: `chart.rows = [{ t: 0, energy: -1.3 }, …]` on an `<iso-chart>` with no\n  `data`.\n- `iso.format(x)`: a number to read (3 figures, 2.3×10⁻³). `iso.tokens()`: the theme, as `t` above.\n- In CSS: `var(--text)`, `var(--text-soft)`, `var(--text-faint)`, `var(--line)`, `var(--lattice)`, `var(--growth)`,\n  `var(--malachite)`, `var(--rose)`, `var(--font-ui)`, `var(--font-text)`.\n\n## Rules (write_artifact checks them, and refuses a file that breaks one)\n\n1. Every file read (`data=\"…\"`, `src=\"…\"`, `iso.data(\"…\")`) is in `uses`, and exists: call `read_data` first.\n2. Every column named is in its file, spelt as `read_data` gives it.\n3. No colour, font family or border-radius of its own: no `#hex`, `rgb(…)`, `white`, `Arial`. Use the tokens.\n4. No network: no `http…` address, no `<script src>`, no `fetch`. The kit is given; everything else is in the file.\n5. Under 200 kB: data stays in data files.\n6. No text that tells how to use it (\"drag to rotate\", \"click here\"): a label says what a thing is.\n\n## What good is\n\nEvery panel answers a question about the data, with a caption saying what to see. Numbers are read out. Axes say\nwhat they measure, with units. Controls change what is drawn at once. Nothing is decoration.\n";
/** Each recipe: when it's the one, and a complete working artifact to change. */
export const RECIPES: Record<string, { about: string; html: string }> = {
 "dashboard": {
  "about": "a dashboard of one data file: numbers, charts and a table, in markup only",
  "html": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>The pendulum's period</title>\n<meta name=\"description\" content=\"Forty timed swings at eight lengths: how the period grows with length, how close it comes to 2π√(L/g), and how much the trials scatter.\">\n<meta name=\"isorite:kit\" content=\"1\">\n<meta name=\"isorite:uses\" content=\"pendulum.csv\">\n</head>\n<body>\n<!-- Recipe 1: a dashboard of one data file, in markup only. Change: the file, the numbers, the charts' columns, the\n     captions. Every column named here must be one read_data gave. -->\n<iso-page>\n  <header>\n    <h1>The pendulum's period</h1>\n    <p>Does a longer pendulum swing slower, and by as much as theory says?</p>\n  </header>\n  <iso-grid>\n    <iso-panel class=\"wide\">\n      <h2>In numbers <span>40 swings</span></h2>\n      <iso-stats>\n        <iso-stat data=\"pendulum.csv\" column=\"period_s\" of=\"min\" label=\"shortest period (s)\" tone=\"blue\"></iso-stat>\n        <iso-stat data=\"pendulum.csv\" column=\"period_s\" of=\"max\" label=\"longest period (s)\" tone=\"gold\"></iso-stat>\n        <iso-stat data=\"pendulum.csv\" column=\"temp_c\" of=\"mean\" label=\"mean temperature (°C)\"></iso-stat>\n        <iso-stat data=\"pendulum.csv\" column=\"trial\" of=\"count\" label=\"swings timed\"></iso-stat>\n      </iso-stats>\n    </iso-panel>\n    <iso-panel>\n      <h2>Period against length</h2>\n      <iso-chart data=\"pendulum.csv\" type=\"dot\" x=\"length_m\" y=\"period_s\" x-label=\"length (m)\" y-label=\"period (s)\"></iso-chart>\n      <p>The period rises with length, more slowly as the pendulum gets longer: a square root.</p>\n    </iso-panel>\n    <iso-panel>\n      <h2>On log axes <span>slope ½ is √L</span></h2>\n      <iso-chart data=\"pendulum.csv\" type=\"dot\" x=\"length_m\" y=\"period_s\" x-scale=\"log\" y-scale=\"log\" x-label=\"length (m)\" y-label=\"period (s)\"></iso-chart>\n      <p>A straight line here is a power law; its slope, near one half, is the exponent.</p>\n    </iso-panel>\n    <iso-panel class=\"wide\">\n      <h2>Each trial <span>the scatter is the stopwatch</span></h2>\n      <iso-chart data=\"pendulum.csv\" type=\"line\" x=\"length_m\" y=\"period_s\" by=\"trial\" height=\"200\" x-label=\"length (m)\" y-label=\"period (s)\"></iso-chart>\n    </iso-panel>\n    <iso-panel class=\"wide\">\n      <h2>The measurements</h2>\n      <iso-table data=\"pendulum.csv\" columns=\"length_m trial period_s temp_c\" limit=\"40\"></iso-table>\n    </iso-panel>\n  </iso-grid>\n</iso-page>\n</body>\n</html>\n"
 },
 "compare": {
  "about": "two data files with the same columns, compared: together on one chart, and side by side",
  "html": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>A lid against an open mug</title>\n<meta name=\"description\" content=\"Two mugs of the same coffee cooling for an hour, one with a lid: their temperature together, the gap between them, and where each stands at a chosen minute.\">\n<meta name=\"isorite:kit\" content=\"1\">\n<meta name=\"isorite:uses\" content=\"mug-open.csv mug-lid.csv\">\n</head>\n<body>\n<!-- Recipe 2: comparing two data files with the same columns. data=\"a.csv b.csv\" reads both as one table with a\n     column `file` (\"mug-open\", \"mug-lid\"), so by=\"file\" draws one series each and where=\"file=…\" picks one.\n     Change: the files, the columns, the captions. -->\n<iso-page>\n  <header>\n    <h1>A lid against an open mug</h1>\n    <p>How much longer does a lid keep coffee hot?</p>\n  </header>\n  <iso-grid>\n    <iso-panel class=\"wide\">\n      <h2>At one minute</h2>\n      <iso-row>\n        <iso-slider name=\"t\" label=\"minute\" min=\"0\" max=\"60\" step=\"2\" value=\"20\" digits=\"0\"></iso-slider>\n        <iso-select name=\"scale\" label=\"temperature scale\" options=\"linear log\"></iso-select>\n      </iso-row>\n      <iso-stats>\n        <iso-stat data=\"mug-open.csv\" column=\"temp_c\" of=\"last\" where=\"t_min<=$t\" label=\"open (°C)\" tone=\"blue\"></iso-stat>\n        <iso-stat data=\"mug-lid.csv\" column=\"temp_c\" of=\"last\" where=\"t_min<=$t\" label=\"with a lid (°C)\" tone=\"gold\"></iso-stat>\n        <iso-stat data=\"mug-open.csv\" column=\"temp_c\" of=\"last\" label=\"open after the hour (°C)\"></iso-stat>\n        <iso-stat data=\"mug-lid.csv\" column=\"temp_c\" of=\"last\" label=\"lid after the hour (°C)\"></iso-stat>\n      </iso-stats>\n    </iso-panel>\n    <iso-panel class=\"wide\">\n      <h2>Both, cooling</h2>\n      <iso-chart data=\"mug-open.csv mug-lid.csv\" x=\"t_min\" y=\"temp_c\" by=\"file\" at=\"t\" y-scale=\"$scale\" x-label=\"time (min)\" y-label=\"temperature (°C)\" height=\"300\"></iso-chart>\n      <p>Both fall fast at first and slower as they near the room's 21 °C; the lid halves the early loss.</p>\n    </iso-panel>\n    <iso-panel>\n      <h2>Open</h2>\n      <iso-table data=\"mug-open.csv\" limit=\"12\"></iso-table>\n    </iso-panel>\n    <iso-panel>\n      <h2>With a lid</h2>\n      <iso-table data=\"mug-lid.csv\" limit=\"12\"></iso-table>\n    </iso-panel>\n  </iso-grid>\n</iso-page>\n</body>\n</html>\n"
 },
 "simulation": {
  "about": "a simulation with parameters, play and reset, drawn on a canvas, with a live chart (a script)",
  "html": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>A damped spring</title>\n<meta name=\"description\" content=\"A mass on a spring, integrated live: change the stiffness and the damping and see the motion, the energy draining away, and the period against theory's.\">\n<meta name=\"isorite:kit\" content=\"1\">\n<meta name=\"isorite:uses\" content=\"\">\n<style>\n  /* Layout only. */\n  .readout { margin-top: 12px; }\n</style>\n</head>\n<body>\n<!-- Recipe 3: a simulation with parameters and play. The parts to change are marked CHANGE: the state (what the\n     model is), step() (how it moves), draw() (what's on the canvas), and what's measured. The rest stays. -->\n<iso-page>\n  <header>\n    <h1>A damped spring</h1>\n    <p>How do stiffness and damping shape an oscillation?</p>\n  </header>\n  <iso-grid>\n    <iso-panel class=\"wide\">\n      <h2>The model</h2>\n      <iso-row>\n        <iso-slider name=\"k\" label=\"stiffness k (N/m)\" min=\"1\" max=\"40\" step=\"0.5\" value=\"10\" digits=\"1\"></iso-slider>\n        <iso-slider name=\"c\" label=\"damping c (kg/s)\" min=\"0\" max=\"2\" step=\"0.05\" value=\"0.3\" digits=\"2\"></iso-slider>\n      </iso-row>\n      <iso-row>\n        <iso-toggle name=\"playing\" label=\"play\" value=\"true\"></iso-toggle>\n        <button type=\"button\" class=\"iso-button\" id=\"reset\">reset</button>\n      </iso-row>\n      <iso-stats class=\"readout\">\n        <iso-stat id=\"time\" label=\"time (s)\"></iso-stat>\n        <iso-stat id=\"energy\" label=\"energy left\" tone=\"gold\"></iso-stat>\n        <iso-stat id=\"period\" label=\"period, theory (s)\" tone=\"blue\"></iso-stat>\n      </iso-stats>\n    </iso-panel>\n    <iso-panel>\n      <h2>The mass</h2>\n      <iso-canvas id=\"scene\" height=\"300\"></iso-canvas>\n    </iso-panel>\n    <iso-panel>\n      <h2>Energy <span>a share of the start</span></h2>\n      <iso-chart id=\"chart\" x=\"t\" y=\"energy\" x-label=\"time (s)\" y-label=\"energy left\" height=\"300\"></iso-chart>\n      <p>With no damping the energy stays; damping drains it, faster the larger c is.</p>\n    </iso-panel>\n  </iso-grid>\n</iso-page>\n<script>\n  // CHANGE: the model's state and its start.\n  const m = 1;\n  let s, history;\n  function reset() { s = { t: 0, x: 1, v: 0 }; history = []; }\n  reset();\n  const energy = () => 0.5 * m * s.v * s.v + 0.5 * iso.state.k * s.x * s.x;\n  let e0 = energy();\n\n  // CHANGE: one step of the model (here semi-implicit Euler, small steps).\n  function step(dt) {\n    const a = (-iso.state.k * s.x - iso.state.c * s.v) / m;\n    s.v += a * dt;\n    s.x += s.v * dt;\n    s.t += dt;\n  }\n\n  // CHANGE: what's drawn. t is the theme: t.line, t.text, t.soft, t.faint, t.lattice, t.growth, t.ui.\n  const scene = document.getElementById(\"scene\");\n  scene.draw = (ctx, w, h, t) => {\n    const cx = w / 2, y0 = 24, rest = h * 0.5, y = rest + s.x * h * 0.3;\n    ctx.strokeStyle = t.line; ctx.lineWidth = 1;\n    ctx.beginPath(); ctx.moveTo(cx - 60, y0); ctx.lineTo(cx + 60, y0); ctx.stroke();\n    ctx.setLineDash([3, 4]); ctx.beginPath(); ctx.moveTo(cx - 80, rest); ctx.lineTo(cx + 80, rest); ctx.stroke(); ctx.setLineDash([]);\n    // The spring, as a zigzag from the ceiling to the mass.\n    ctx.strokeStyle = t.soft; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.moveTo(cx, y0);\n    for (let i = 1; i < 16; i++) ctx.lineTo(cx + (i % 2 ? 12 : -12), y0 + (y - 20 - y0) * i / 16);\n    ctx.lineTo(cx, y - 20); ctx.stroke();\n    ctx.fillStyle = t.lattice; ctx.fillRect(cx - 20, y - 20, 40, 40);\n    ctx.fillStyle = t.faint; ctx.font = `11px ${t.ui}`; ctx.fillText(\"rest\", cx + 84, rest + 4);\n  };\n\n  // Measured, and shown: the readouts and the chart, a few times a second.\n  const chart = document.getElementById(\"chart\");\n  let since = 0;\n  function show() {\n    document.getElementById(\"time\").value = s.t.toFixed(1);\n    document.getElementById(\"energy\").value = iso.format(energy() / e0);\n    document.getElementById(\"period\").value = iso.format(2 * Math.PI * Math.sqrt(m / iso.state.k));\n    chart.rows = history;\n  }\n\n  iso.loop((dt) => {\n    if (!iso.state.playing) return;\n    for (let i = 0; i < 20; i++) step(dt / 20);\n    scene.redraw();\n    since += dt;\n    if (since > 0.1) { since = 0; history.push({ t: +s.t.toFixed(2), energy: energy() / e0 }); if (history.length > 600) history.shift(); show(); }\n  });\n  iso.watch((name) => { if (name === \"k\") { e0 = energy(); } show(); scene.redraw(); });\n  document.getElementById(\"reset\").addEventListener(\"click\", () => { reset(); e0 = energy(); show(); scene.redraw(); });\n  show();\n</script>\n</body>\n</html>\n"
 },
 "explorable": {
  "about": "an explorable explanation: inputs, numbers derived from them, and linked views (a script)",
  "html": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>Why a fast wheel turns backwards</title>\n<meta name=\"description\" content=\"Sample a sine too slowly and a slower one appears: choose the signal's frequency and the sampling rate, and see the samples, the wave they seem to come from, and where every frequency lands.\">\n<meta name=\"isorite:kit\" content=\"1\">\n<meta name=\"isorite:uses\" content=\"\">\n</head>\n<body>\n<!-- Recipe 4: an explorable explanation. An input, numbers derived from it, and linked views that all follow the same\n     state; captions say what to see. CHANGE: the inputs (sliders), derive() (the numbers), the drawing, and the\n     chart's rows. Keep: every view redrawn from iso.state in one place, update(). -->\n<iso-page>\n  <header>\n    <h1>Why a fast wheel turns backwards</h1>\n    <p>Sampled too slowly, a signal is indistinguishable from a slower one. Which one, and when?</p>\n  </header>\n  <iso-grid>\n    <iso-panel class=\"wide\">\n      <h2>The signal and the sampling</h2>\n      <iso-row>\n        <iso-slider name=\"f\" label=\"signal (Hz)\" min=\"0.2\" max=\"12\" step=\"0.1\" value=\"7\" digits=\"1\"></iso-slider>\n        <iso-slider name=\"fs\" label=\"samples per second\" min=\"2\" max=\"24\" step=\"1\" value=\"8\" digits=\"0\"></iso-slider>\n      </iso-row>\n      <iso-stats>\n        <iso-stat id=\"nyquist\" label=\"Nyquist limit (Hz)\" tone=\"blue\"></iso-stat>\n        <iso-stat id=\"apparent\" label=\"what the samples show (Hz)\" tone=\"gold\"></iso-stat>\n        <iso-stat id=\"verdict\" label=\"faithful?\"></iso-stat>\n      </iso-stats>\n    </iso-panel>\n    <iso-panel class=\"wide\">\n      <h2>One second <span>the signal, its samples, and the slower wave through them</span></h2>\n      <iso-canvas id=\"wave\" height=\"260\"></iso-canvas>\n      <p>Gold dots are the samples. Above the Nyquist limit the blue wave, slower, passes through every one of them as\n        well as the true signal does: from the samples alone, the two can't be told apart.</p>\n    </iso-panel>\n    <iso-panel class=\"wide\">\n      <h2>Where every frequency lands</h2>\n      <iso-chart id=\"fold\" x=\"signal\" y=\"apparent\" at=\"f\" x-label=\"signal (Hz)\" y-label=\"frequency the samples show (Hz)\" height=\"220\"></iso-chart>\n      <p>The frequency seen climbs with the signal's up to half the sampling rate, then folds back down:\n        $f_\\text{seen} = |f - f_s \\operatorname{round}(f / f_s)|$. See <iso-note href=\"signals/sampling\">sampling</iso-note>.</p>\n    </iso-panel>\n  </iso-grid>\n</iso-page>\n<script>\n  // CHANGE: the numbers derived from the inputs.\n  function derive(f, fs) {\n    const nyquist = fs / 2;\n    const folded = Math.abs(f - fs * Math.round(f / fs));\n    return { nyquist, apparent: folded, faithful: f < nyquist };\n  }\n\n  // CHANGE: the drawing. t is the theme (t.line, t.soft, t.faint, t.lattice, t.growth, t.ui).\n  const wave = document.getElementById(\"wave\");\n  wave.draw = (ctx, w, h, t) => {\n    const { f, fs } = iso.state, d = derive(f, fs), mid = h / 2, amp = h * 0.38;\n    const X = (s) => 40 + s * (w - 60), Y = (v) => mid - v * amp;\n    ctx.strokeStyle = t.line; ctx.lineWidth = 1;\n    ctx.beginPath(); ctx.moveTo(X(0), mid); ctx.lineTo(X(1), mid); ctx.stroke();\n    const curve = (freq, colour, width) => {\n      ctx.strokeStyle = colour; ctx.lineWidth = width; ctx.beginPath();\n      for (let i = 0; i <= 600; i++) { const s = i / 600, v = Math.sin(2 * Math.PI * freq * s); i ? ctx.lineTo(X(s), Y(v)) : ctx.moveTo(X(s), Y(v)); }\n      ctx.stroke();\n    };\n    curve(f, t.soft, 1);\n    // The slower wave through the same samples: the signal less the nearest whole number of sampling rates.\n    if (!d.faithful) curve(f - fs * Math.round(f / fs), t.lattice, 2);\n    ctx.fillStyle = t.growth;\n    for (let k = 0; k <= fs; k++) { const s = k / fs; ctx.beginPath(); ctx.arc(X(s), Y(Math.sin(2 * Math.PI * f * s)), 4, 0, 2 * Math.PI); ctx.fill(); }\n    ctx.fillStyle = t.faint; ctx.font = `11px ${t.ui}`; ctx.fillText(\"0 s\", X(0) - 8, h - 6); ctx.fillText(\"1 s\", X(1) - 8, h - 6);\n  };\n\n  // One place redraws every view from the state.\n  const fold = document.getElementById(\"fold\");\n  function update() {\n    const { f, fs } = iso.state, d = derive(f, fs);\n    document.getElementById(\"nyquist\").value = iso.format(d.nyquist);\n    document.getElementById(\"apparent\").value = iso.format(d.apparent);\n    document.getElementById(\"verdict\").value = d.faithful ? \"yes\" : \"no: aliased\";\n    // CHANGE: the chart's rows, computed from the state.\n    const rows = [];\n    for (let s = 0; s <= 12; s += 0.05) rows.push({ signal: +s.toFixed(2), apparent: derive(s, fs).apparent });\n    fold.rows = rows;\n    wave.redraw();\n  }\n  iso.watch(update);\n  update();\n</script>\n</body>\n</html>\n"
 },
 "viewer": {
  "about": "a 3D model's viewer (glTF, GLB, STL, OBJ), with what it is beside it",
  "html": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>The corner bracket</title>\n<meta name=\"description\" content=\"The printed corner bracket in 3D, with its dimensions and the notes on how it was designed and tested.\">\n<meta name=\"isorite:kit\" content=\"1\">\n<meta name=\"isorite:uses\" content=\"bracket.stl\">\n</head>\n<body>\n<!-- Recipe 5: a 3D model's viewer, with what it is beside it. iso-model shows glTF, GLB, STL and OBJ; list the file\n     in isorite:uses. CHANGE: the model's file, the numbers, the notes it links to. -->\n<iso-page>\n  <header>\n    <h1>The corner bracket</h1>\n    <p>The part as printed: an L of two plates, 6 cm by 5 cm.</p>\n  </header>\n  <iso-grid style=\"--cols: 3\">\n    <iso-panel class=\"wide\">\n      <h2>The part <span>bracket.stl</span></h2>\n      <iso-model src=\"bracket.stl\" height=\"380\"></iso-model>\n    </iso-panel>\n    <iso-panel>\n      <h2>Size</h2>\n      <iso-stats>\n        <iso-stat label=\"long arm (mm)\" value=\"60\" tone=\"blue\"></iso-stat>\n        <iso-stat label=\"short arm (mm)\" value=\"50\"></iso-stat>\n        <iso-stat label=\"thickness (mm)\" value=\"10\"></iso-stat>\n      </iso-stats>\n    </iso-panel>\n    <iso-panel>\n      <h2>Printed</h2>\n      <iso-stats>\n        <iso-stat label=\"infill\" value=\"40%\"></iso-stat>\n        <iso-stat label=\"mass (g)\" value=\"31\" tone=\"gold\"></iso-stat>\n      </iso-stats>\n    </iso-panel>\n    <iso-panel>\n      <h2>Notes</h2>\n      <p><iso-note href=\"design/bracket-loads\">The loads it takes</iso-note>, and\n        <iso-note href=\"design/print-settings\">how it was printed</iso-note>.</p>\n    </iso-panel>\n  </iso-grid>\n</iso-page>\n</body>\n</html>\n"
 }
};
